INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerk-Protokolle immer nur für drahtlose Netzwerke gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzwerk-Protokolle für ein IT-System auswähle?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerk-Protokolle sind gebräuchlich?', 5, '[{"text": "TCP/IP", "correct": true, "because": "Grundlage Internet"}, {"text": "HTTP", "correct": true, "because": "Web-Kommunikation"}, {"text": "Büroprotokoll", "correct": false, "because": "Kein Protokoll"}, {"text": "Farbprotokoll", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerk-Protokolle regeln die Datenübertragung. b) Sie sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerk-Protokolle für ein IT-System plane?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Sichert Übertragung"}, {"text": "Kompatibilität", "correct": false, "because": "Ermöglicht Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerk-Protokolle nur für große Netzwerke gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Netzwerk-Protokollen?', 3, '[{"text": "Zuverlässige Kommunikation", "correct": true, "because": "Regeln Datenfluss"}, {"text": "Schnellste Implementierung", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Regeln", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Netzwerk-Protokolle?', 5, '[{"text": "Standardisierung", "correct": true, "because": "Ermöglicht Interoperabilität"}, {"text": "Datenintegrität", "correct": true, "because": "Sichert Übertragung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) TCP/IP ist ein Netzwerk-Protokoll. b) Es ist immer unsicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerk-Protokolle effektiv einzusetzen?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Sichert Kommunikation"}, {"text": "Routing", "correct": false, "because": "Leitet Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerk-Protokolle immer optional?', 2, '[{"text": "Nein", "correct": true, "because": "Erforderlich für Kommunikation"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Netzwerk-Protokolle?', 4, '[{"text": "Interoperabilität", "correct": true, "because": "Ermöglicht Zusammenarbeit"}, {"text": "Datenintegrität", "correct": true, "because": "Sichert Übertragung"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerk-Protokolle nur für LANs gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WANs, Internet"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Netzwerk-Protokolle für ein IT-System auszuwählen?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Protokoll"}, {"text": "Günstigste Option", "correct": false, "because": "Funktion wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) HTTP ist ein Netzwerk-Protokoll. b) Es ist immer unsicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicher mit HTTPS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerk-Protokollen?', 5, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Übertragung"}, {"text": "Kompatibilität", "correct": true, "because": "Ermöglicht Kommunikation"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Netzwerk-Protokolle auswähle?', 3, '[{"text": "Übertragungsgeschwindigkeit", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Sicherheitsfunktionen", "correct": false, "because": "Schützen Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerk-Protokolle immer für große Netzwerke geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerk-Protokolle nur für Internet-Kommunikation gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Netzwerk-Protokolle?', 4, '[{"text": "Standardisierung", "correct": true, "because": "Sichert Interoperabilität"}, {"text": "Schnellste Implementierung", "correct": false, "because": "Funktion zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
